// Eingabe vereinheitlichen (Aufruf durch Ally oder Testlauf)
const j = $input.first().json || {};
return [{ json: { nutzer: String(j.nutzer || '').trim(), kunde: String(j.kunde || '').trim() } }];

// Kunde finden: aktive Papierkram-Kunden nach Name, Kundennummer, Mail oder Website durchsuchen
const s = v => String(v ?? '').trim();
const e = $('Eingabe').first().json;
const seiten = $('Kunden (Papierkram)').all().map(i => i.json || {});
const fehler = seiten.some(p => p.error);
const alle = seiten.flatMap(p => Array.isArray(p.entries) ? p.entries : []).filter(c => c.contact_type === 'customer');
const aktiv = alle.filter(c => !c.record_state || c.record_state === 'active');
const norm = v => s(v).toLowerCase().replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss')
  .replace(/\b(gmbh|mbh|gbr|ug|ag|kg|ohg|e\s?v|co)\b/g, ' ').replace(/[^a-z0-9]+/g, ' ').trim();
const suche = (liste, q) => {
  const nq = norm(q);
  if (!nq) return [];
  const nr = s(q).match(/^k-?0*(\d+)$/i);
  if (nr) return liste.filter(c => s(c.customer_no).replace(/^k-?0*/i, '') === nr[1]);
  const exakt = liste.filter(c => norm(c.name) === nq);
  if (exakt.length) return exakt;
  const enthalten = liste.filter(c => norm(c.name).includes(nq) || (nq.length >= 4 && (norm(c.email).includes(nq) || norm(c.website).includes(nq))));
  if (enthalten.length) return enthalten;
  const worte = nq.split(' ').filter(w => w.length >= 3);
  return worte.length ? liste.filter(c => worte.every(w => norm(c.name + ' ' + c.email + ' ' + c.website).includes(w))) : [];
};
const treffer = suche(aktiv, e.kunde);
const kurz = c => ({ name: s(c.name), kundennummer: s(c.customer_no) });
let status = 'eindeutig';
if (fehler && !alle.length) status = 'papierkram_fehler';
else if (!s(e.kunde)) status = 'kein_kunde_angegeben';
else if (!treffer.length) status = suche(alle, e.kunde).length ? 'nur_archiviert' : 'nicht_gefunden';
else if (treffer.length > 1) status = 'mehrdeutig';
return [{ json: {
  eindeutig: status === 'eindeutig',
  status,
  kunde: status === 'eindeutig' ? treffer[0] : null,
  kandidaten: treffer.slice(0, 10).map(kurz),
  archiviert: status === 'nur_archiviert' ? suche(alle, e.kunde).slice(0, 5).map(kurz) : [],
  aktive_kunden: status === 'nicht_gefunden' ? aktiv.map(kurz) : []
} }];

// Überblick bauen: alle Quellen zu einem Kunden zusammenführen (Chat-Nachricht + PDF-HTML)
const s = v => String(v ?? '').trim();
const arr = v => Array.isArray(v) ? v : [];
const esc = v => s(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const euro = v => Number(v || 0).toLocaleString('de-DE', { style: 'currency', currency: 'EUR' });
const std = v => Number(v || 0).toLocaleString('de-DE', { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const datum = iso => iso ? DateTime.fromISO(String(iso).slice(0, 10), { zone: 'Europe/Berlin' }).toFormat('dd.LL.yyyy') : '';
const seiten = name => { try { return $(name).all().map(i => i.json || {}); } catch (e) { return []; } };
const eintraege = name => seiten(name).flatMap(p => Array.isArray(p.entries) ? p.entries : []);
const fehlerIn = name => seiten(name).some(p => p.error);

const jetzt = DateTime.now().setZone('Europe/Berlin');
const heute = jetzt.startOf('day');
const eingabe = $('Eingabe').first().json;
const k = $('Kunde finden').first().json.kunde;
const db = (seiten('Daten (DB)')[0]) || {};

// ---------- Projekte und Budgets (Papierkram) ----------
const mapProjekte = arr(db.projekte_map);
const mapPkIds = new Set(mapProjekte.map(p => String(p.pk)));
const kundeVon = p => String((p.customer && p.customer.id) || (p.company && p.company.id) || p.company_id || p.customer_id || '');
// Zuordnung nach Papierkram (fuehrend); das Sync-Gedaechtnis nur, wenn Papierkram keinen Kunden liefert. Standardprojekte "Kein Projekt" ausblenden.
const projekteAlle = eintraege('Projekte (Papierkram)').filter(p => !p.customer_default && (kundeVon(p) ? kundeVon(p) === String(k.id) : mapPkIds.has(String(p.id))));
const heuteIso = DateTime.now().setZone('Europe/Berlin').toISODate();
const projekte = projekteAlle.filter(p => (!p.record_state || p.record_state === 'active') && (!p.start_date || String(p.start_date).slice(0, 10) <= heuteIso));
const pk1 = (seiten('Projektbudgets (PK 1)')[0]) || {};
const budgets = arr(pk1.projekte).filter(b => projekte.some(p => String(p.id) === String(b.id)));
const budgetVon = id => budgets.find(b => String(b.id) === String(id));
const projektZeilen = projekte.map(p => {
  const b = budgetVon(p.id);
  let budget = 'ohne Budget';
  if (b && b.budget_art === 'Geld') budget = b.prozent === null ? euro(b.budget_eur) + ' Budget (kein Stundensatz hinterlegt)' : Math.round(b.prozent) + ' % von ' + euro(b.budget_eur) + ' verbraucht, Rest ' + euro(b.rest_eur);
  else if (b) budget = Math.round(b.prozent) + ' % von ' + std(b.budget_stunden) + ' h verbraucht, Rest ' + std(b.rest_stunden) + ' h';
  const zeitraum = (p.start_date || p.end_date) ? (datum(p.start_date) || '…') + ' – ' + (datum(p.end_date) || 'offen') : '';
  if (p.end_date && String(p.end_date).slice(0, 10) < heuteIso) budget += ' · Laufzeit beendet';
  // Chat: je Projekt mehrere kurze Zeilen (Name, Laufzeit, Budget, Verbrauch)
  const kurz = iso => iso ? DateTime.fromISO(String(iso).slice(0, 10), { zone: 'Europe/Berlin' }).toFormat('dd.LL.yy') : '';
  const z = [s(p.name)];
  if (p.start_date || p.end_date) z.push((kurz(p.start_date) || '…') + ' – ' + (kurz(p.end_date) || 'offen'));
  if (!b) z.push('Ohne Budget');
  else if (b.budget_art === 'Geld') {
    z.push('Budget: ' + euro(b.budget_eur));
    z.push(b.prozent === null ? 'Verbrauch unbekannt (kein Stundensatz hinterlegt)' : 'Verbraucht: ' + euro(b.verbraucht_eur) + ' (' + Math.round(b.prozent) + ' %), Rest: ' + euro(b.rest_eur));
  } else {
    z.push('Budget: ' + std(b.budget_stunden) + ' h');
    z.push('Verbraucht: ' + std(b.stunden) + ' h (' + Math.round(b.prozent) + ' %), Rest: ' + std(b.rest_stunden) + ' h');
  }
  if (p.end_date && String(p.end_date).slice(0, 10) < heuteIso) z.push('Laufzeit beendet');
  return { name: s(p.name), zeitraum, budget, prozent: b ? b.prozent : null, zeilen: z };
});

// ---------- Rechnungen (Papierkram) ----------
const rechnungen = eintraege('Rechnungen (Papierkram)').filter(r => s(r.customer_no) && s(r.customer_no) === s(k.customer_no));
const istOffen = r => {
  const st = s(r.state).toLowerCase();
  return !['paid', 'canceled', 'cancelled', 'draft'].includes(st) && (!r.record_state || r.record_state === 'active') && !r.paid_at_date;
};
const betragOffen = r => Number(r.outstanding_amount) > 0 ? Number(r.outstanding_amount) : Number(r.total_gross || 0);
const offen = rechnungen.filter(istOffen).map(r => {
  const faellig = r.due_date ? DateTime.fromISO(String(r.due_date).slice(0, 10), { zone: 'Europe/Berlin' }) : null;
  const tage = faellig ? Math.floor(heute.diff(faellig, 'days').days) : null;
  return { nr: s(r.invoice_no) || ('#' + r.id), name: s(r.name), betrag: betragOffen(r), faellig: datum(r.due_date), ueberfaellig: tage !== null && tage > 0, tage };
}).sort((a, b) => (b.tage ?? -999) - (a.tage ?? -999));
const jahr = String(jetzt.year);
const zaehlt = r => (!r.record_state || r.record_state === 'active') && !['draft', 'canceled', 'cancelled'].includes(s(r.state).toLowerCase()) && !/-S$/i.test(s(r.invoice_no));
const umsatzJahr = rechnungen.filter(r => zaehlt(r) && String(r.document_date || '').startsWith(jahr)).reduce((a, r) => a + Number(r.total_net || 0), 0);
const anzahlJahr = rechnungen.filter(r => zaehlt(r) && String(r.document_date || '').startsWith(jahr) && Number(r.total_net) > 0).length;
const letzte = rechnungen.filter(zaehlt).sort((a, b) => String(b.document_date).localeCompare(String(a.document_date)))[0];

// ---------- Stunden (timeBuzzer, führend) ----------
const tile = s(db.tb_tile);
const tileName = {};
mapProjekte.forEach(p => { if (p.tile) tileName[String(p.tile)] = s(p.name); });
const gesehen = new Set();
const akt = [];
for (const seite of seiten('timeBuzzer Aktivitäten')) for (const a of arr(seite.activities)) { if (!gesehen.has(String(a.id))) { gesehen.add(String(a.id)); akt.push(a); } }
const monat0 = jetzt.startOf('month'), monat1 = monat0.minus({ months: 1 });
const stunden = { akt: 0, vor: 0, laeuft: false, proProjekt: {} };
if (tile) for (const a of akt) {
  if (!Array.isArray(a.tiles) || String(a.tiles[0]) !== tile) continue;
  if (!a.endDate) { stunden.laeuft = true; continue; }
  const st = DateTime.fromISO(a.startDate, { zone: 'utc' }).setZone('Europe/Berlin');
  const h = DateTime.fromISO(a.endDate, { zone: 'utc' }).diff(DateTime.fromISO(a.startDate, { zone: 'utc' }), 'minutes').minutes / 60;
  if (st >= monat0) { stunden.akt += h; const pn = tileName[String(a.tiles[1])] || 'ohne Projekt'; stunden.proProjekt[pn] = (stunden.proProjekt[pn] || 0) + h; }
  else if (st >= monat1) stunden.vor += h;
}
const monatName = d => d.setLocale('de').toFormat('LLLL yyyy');

// ---------- Mails und Entwürfe (nur Postfächer des Nutzers) ----------
const FREEMAIL = new Set(['web.de', 'gmx.de', 'gmx.net', 'gmx.at', 'gmx.ch', 'gmail.com', 'googlemail.com', 'me.com', 'icloud.com', 'mac.com', 'outlook.com', 'outlook.de', 'hotmail.com', 'hotmail.de', 'live.com', 'live.de', 'yahoo.com', 'yahoo.de', 't-online.de', 'aol.com', 'aol.de', 'freenet.de', 'posteo.de', 'mail.de', 'online.de', 'arcor.de', 'email.de', 'protonmail.com', 'proton.me',
  // eigene Domains (Postfächer aus ally_postfaecher, über Daten (DB)) gelten nie als Kunden-Domain
  ...arr(db.eigene_domains).map(d => s(d).toLowerCase()).filter(Boolean)]);
const mailVon = v => { const m = s(v).toLowerCase().match(/[a-z0-9._%+\-]+@[a-z0-9.\-]+\.[a-z]{2,}/); return m ? m[0] : ''; };
const domainVon = v => { const m = mailVon(v); return m ? m.split('@')[1] : ''; };
const personen = eintraege('Ansprechpartner (Papierkram)');
const adressen = new Set([k.email, ...personen.map(p => p.email), ...rechnungen.map(r => r.billing && r.billing.email), ...rechnungen.map(r => r.sent_to)].map(mailVon).filter(Boolean));
const domains = new Set([...adressen].map(a => a.split('@')[1]).filter(d => d && !FREEMAIL.has(d)));
const web = s(k.website).toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0];
if (web && !FREEMAIL.has(web)) domains.add(web);
const GENERISCH = /^(va\b|allgemein|kein projekt|projekt$|support|wartung|webhosting|website$)/i;
const stichworte = [...new Set(projekte.map(p => s(p.name)).filter(n => n.length >= 6 && !GENERISCH.test(n)))];
// Mails gehoeren nur ueber Absenderadresse oder Domain (aus Papierkram) zum Kunden, nie ueber Woerter im Betreff
const passt = adr => {
  const a = mailVon(adr), d = domainVon(adr);
  if (a && adressen.has(a)) return true;
  return !!(d && domains.has(d) && !FREEMAIL.has(d));
};
// Nur echte Mails (Kategorie kunde oder keine), keine System-Reports
const mails = arr(db.mails).filter(m => ['kunde', 'keine'].includes(s(m.kategorie_key)) && passt(m.sender)).slice(0, 10);
const entwuerfe = arr(db.entwuerfe).filter(r => passt(r.antwort_an || r.absender));

// ---------- Termine (Kalender des Nutzers, nächste 30 Tage) ----------
const kern = s(k.name).replace(/\b(gmbh|mbh|gbr|ug|ag|kg|ohg|e\.\s?v\.|ev|co\.?|haftungsbeschränkt)\b/gi, '').replace(/[&()]/g, ' ').replace(/\s+/g, ' ').trim();
const terminWorte = [kern, ...stichworte].filter(w => w.length >= 4).map(w => w.toLowerCase());
const kalenderFehler = !s(db.kalender_id) || fehlerIn('Termine (Kalender)');
const termine = seiten('Termine (Kalender)').filter(e => e && e.id && e.start).filter(e => {
  const t = (s(e.summary) + ' ' + s(e.description) + ' ' + s(e.location)).toLowerCase();
  return terminWorte.some(w => t.includes(w));
}).map(e => {
  const st = e.start.dateTime ? DateTime.fromISO(e.start.dateTime).setZone('Europe/Berlin') : DateTime.fromISO(e.start.date, { zone: 'Europe/Berlin' });
  return { wann: e.start.dateTime ? st.setLocale('de').toFormat('ccc dd.LL. HH:mm') : st.setLocale('de').toFormat('ccc dd.LL.') + ' ganztägig', titel: s(e.summary) || '(ohne Titel)' };
});

// ---------- Ausgabe ----------
const unvollstaendig = name => { const p = seiten(name); return p.length > 0 && !!p[p.length - 1].has_more; };
const pkFehler = fehlerIn('Projekte (Papierkram)') || fehlerIn('Rechnungen (Papierkram)') || unvollstaendig('Projekte (Papierkram)') || unvollstaendig('Rechnungen (Papierkram)');
const tbFehler = fehlerIn('timeBuzzer Aktivitäten') || (tile && !akt.length);
const offenSumme = offen.reduce((a, r) => a + r.betrag, 0);
const ueberSumme = offen.filter(r => r.ueberfaellig).reduce((a, r) => a + r.betrag, 0);
const kontakt = [s(k.customer_no), s(k.email), s(k.phone), web].filter(Boolean);
const ansprech = personen.filter(p => s(p.first_name) || s(p.last_name)).map(p => [s(p.title), s(p.first_name), s(p.last_name)].filter(Boolean).join(' ') + (s(p.email) ? ' (' + s(p.email) + ')' : '')).slice(0, 3);

const abschnitte = [];
abschnitte.push({ titel: 'Projekte', leer: 'Keine laufenden Projekte.', zeilen: [], gruppen: projektZeilen.map(p => p.zeilen), warn: pkFehler ? 'Papierkram war nicht vollständig erreichbar.' : '' });
const rz = [];
if (offen.length) offen.forEach(r => rz.push(r.nr + (r.name ? ' ' + r.name : '') + ': ' + euro(r.betrag) + (r.faellig ? (r.ueberfaellig ? ', seit ' + r.tage + ' Tag' + (r.tage === 1 ? '' : 'en') + ' überfällig' : ', fällig ' + r.faellig) : '')));
else rz.push('Keine offenen Rechnungen.');
rz.push('Umsatz ' + jahr + ': ' + euro(umsatzJahr) + ' netto aus ' + anzahlJahr + ' Rechnung' + (anzahlJahr === 1 ? '' : 'en'));
if (letzte) rz.push('Letzte Rechnung: ' + (s(letzte.invoice_no) || '#' + letzte.id) + ' vom ' + datum(letzte.document_date) + ', ' + euro(letzte.total_net) + ' netto');
abschnitte.push({ titel: 'Rechnungen', zeilen: rz, warn: pkFehler ? 'Papierkram war nicht vollständig erreichbar.' : '' });
const sz = [];
if (!tile) sz.push('Keine Kundschaft in timeBuzzer zugeordnet.');
else {
  sz.push(monatName(monat0) + ': ' + std(stunden.akt) + ' h' + (stunden.laeuft ? ' (plus laufende Erfassung)' : ''));
  Object.entries(stunden.proProjekt).sort((a, b) => b[1] - a[1]).forEach(([n, h]) => sz.push('davon ' + n + ': ' + std(h) + ' h'));
  sz.push(monatName(monat1) + ': ' + std(stunden.vor) + ' h');
}
abschnitte.push({ titel: 'Stunden (timeBuzzer)', zeilen: sz, warn: tbFehler ? 'timeBuzzer war nicht erreichbar.' : '' });
abschnitte.push({ titel: 'Mails (30 Tage)', leer: 'Keine Mails von dieser Kundschaft.', zeilen: mails.map(m => DateTime.fromISO(m.created_at).setZone('Europe/Berlin').toFormat('dd.LL.') + ' ' + mailVon(m.sender) + ': ' + (s(m.subject) || '(ohne Betreff)')) });
if (entwuerfe.length) abschnitte.push({ titel: 'Offene Mail-Entwürfe', zeilen: entwuerfe.map(r => 'mail-' + r.id + ': ' + (s(r.betreff) || '(ohne Betreff)')) });
abschnitte.push({ titel: 'Termine (30 Tage)', leer: kalenderFehler ? 'Kalender nicht abrufbar.' : 'Keine Termine mit dieser Kundschaft im Titel.', zeilen: termine.map(t => t.wann + ' ' + t.titel) });

// Dateiname und Ablage
const slug = s(k.name).toLowerCase().replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 50) || 'kunde';
// Ablageordner aus dokumente_ordner() über Daten (DB) (Stefan 18.10.2026)
const ordner = s(db.ordner_kundenueberblick).replace(/^\/+/, '') || 'Kundenüberblick';
const datei = jetzt.toFormat('yyyy-LL-dd') + '_' + slug + '.pdf';

// Chat-Nachricht
const kopf = 'Kundenüberblick: ' + s(k.name);
// Kopf: Titel allein, danach Kontakt, Ansprechpartner und Kennzahlen als eigene Bloecke (eine Angabe pro Zeile).
// Mailadressen und Website als Link hinter einem kurzen Text statt ausgeschrieben.
const zl = (h, t) => ({ h, t });
const block = (titel, zeilen) => '<p><strong>' + esc(titel) + '</strong></p><ul>' + zeilen.map(z => '<li>' + (typeof z === 'string' ? esc(z) : z.h) + '</li>').join('') + '</ul>';
const blockText = (titel, zeilen) => ['', titel, ...zeilen.map(z => '- ' + (typeof z === 'string' ? z : z.t))];
const mailText = adr => { const lokal = s(adr).split('@')[0]; return /^[a-zäöüß]+$/i.test(lokal) && lokal.length > 2 ? 'E-Mail ' + lokal.charAt(0).toUpperCase() + lokal.slice(1).toLowerCase() : 'E-Mail'; };
const kontaktZeilen = [];
if (s(k.customer_no)) kontaktZeilen.push('Kundennummer ' + s(k.customer_no));
if (mailVon(k.email)) kontaktZeilen.push(zl('<a href="mailto:' + esc(mailVon(k.email)) + '">' + esc(mailText(mailVon(k.email))) + '</a>', mailVon(k.email)));
if (s(k.phone)) kontaktZeilen.push(s(k.phone));
if (web) kontaktZeilen.push(zl('<a href="https://' + esc(web) + '">Website</a>', web));
const ansprechZeilen = personen.filter(p => s(p.first_name) || s(p.last_name)).slice(0, 3).map(p => {
  const name = [s(p.title), s(p.first_name), s(p.last_name)].filter(Boolean).join(' ');
  const m = mailVon(p.email);
  return m ? zl('<a href="mailto:' + esc(m) + '">' + esc(name) + '</a>', name + ' (' + m + ')') : name;
});
const blickZeilen = [
  'Offen: ' + euro(offenSumme) + (ueberSumme ? ' (davon überfällig ' + euro(ueberSumme) + ')' : ''),
  'Umsatz ' + jahr + ': ' + euro(umsatzJahr) + ' netto',
  'Stunden ' + monatName(monat0) + ': ' + std(stunden.akt) + ' h'
];
const html = ['<p><strong>' + esc(kopf) + '</strong></p>'];
const text = [kopf];
if (kontaktZeilen.length) { html.push(block('Kontakt', kontaktZeilen)); text.push(...blockText('Kontakt', kontaktZeilen)); }
if (ansprechZeilen.length) { html.push(block('Ansprechpersonen', ansprechZeilen)); text.push(...blockText('Ansprechpersonen', ansprechZeilen)); }
html.push(block('Auf einen Blick', blickZeilen)); text.push(...blickZeilen.length ? blockText('Auf einen Blick', blickZeilen) : []);
for (const a of abschnitte) {
  html.push('<p><strong>' + esc(a.titel) + '</strong></p>');
  text.push('', a.titel);
  if (a.warn) { html.push('<p>⚠️ ' + esc(a.warn) + '</p>'); text.push('⚠️ ' + a.warn); }
  const gruppen = a.gruppen || (a.zeilen.length ? [a.zeilen] : []);
  if (!gruppen.length) { html.push('<p>' + esc(a.leer) + '</p>'); text.push(a.leer); continue; }
  // Jede Gruppe (z.B. ein Projekt) als eigener Block, getrennt durch eine Leerzeile
  gruppen.forEach((g, i) => {
    html.push('<ul>' + g.map(z => '<li>' + esc(z) + '</li>').join('') + '</ul>');
    if (i > 0) text.push('');
    g.forEach(z => text.push('- ' + z));
  });
}
html.push('<p>📄 <code>' + esc(ordner + '/' + datei) + '</code></p>');
text.push('', 'PDF: ' + ordner + '/' + datei);

// PDF-HTML (A4, Website-Design)
// Corporate Design kommt zentral aus CD 1 (Datenbank, Einstellungen > Unternehmen) (Stefan 17.10.2026)
const CD = $('Corporate Design (CD 1)').first().json;
const C = { dunkel: CD.farben.dunkel, salbei: CD.farben.akzent, salbeiDunkel: CD.farben.akzentDunkel, hell: CD.farben.hell, grau: CD.farben.grau, linie: CD.abgeleitet.tabellenLinie, rot: CD.farben.warnung, weiss: CD.farben.textAufDunkel, nebenDunkel: CD.abgeleitet.dunkelNebentext };
const kachel = (wert, label, warn) => '<div class="kachel"><div class="wert' + (warn ? ' warn' : '') + '">' + esc(wert) + '</div><div class="label">' + esc(label) + '</div></div>';
const tabelle = (kopfzeile, zeilen) => '<table><thead><tr>' + kopfzeile.map(h => '<th>' + esc(h) + '</th>').join('') + '</tr></thead><tbody>' + zeilen.map(z => '<tr>' + z.map((c, i) => '<td' + (typeof c === 'object' && c && c.cls ? ' class="' + c.cls + '"' : '') + '>' + esc(typeof c === 'object' && c ? c.t : c) + '</td>').join('') + '</tr>').join('') + '</tbody></table>';
const leer = t => '<p class="leer">' + esc(t) + '</p>';
const warnP = t => t ? '<p class="hinweis">' + esc(t) + '</p>' : '';
