// Absaetze und Listen in das Chat-Layout umwandeln: Titel fett mit Doppelpunkt, Inhalt direkt darunter, Leerzeile zwischen Bloecken
const layout = h => {
  let s = ohneEmoji(h);
  // Kopfzeile (enthaelt schon einen Doppelpunkt, z.B. "Kundenüberblick: Name") steht allein; Abschnittstitel bekommen einen Doppelpunkt
  s = s.replace(/<p><strong>([^<]+?)<\/strong><\/p>/g, (m, t) => t.includes(':') ? '<strong>' + t + '</strong><br><br>' : '<strong>' + t + (/[?!.]$/.test(t) ? '' : ':') + '</strong><br>');
  s = s.replace(/<p>(Hinweis: [^<]*)<\/p>(?=<ul>)/g, '$1<br>');
  s = s.replace(/<ul>/g, '').replace(/<li>/g, '').replace(/<\/li>/g, '<br>').replace(/<\/ul>/g, '</p>');
  s = s.replace(/<p>/g, '').replace(/(<br>)+\s*<\/p>/g, '</p>').replace(/<\/p>\s*/g, '<br><br>');
  return s.replace(/(<br>)+$/, '');
};
